"""Compare established readable contracts separately from additive static evidence."""

import json

from brewdoc.inspection import readable_projection


def readable_markdown(markdown):
    """Use the generated byte-bound protocol, independently tested with source lookalikes."""
    return readable_projection(markdown)


def rendering_receipt(receipt):
    """Retain every established receipt field and legacy artifact in source order."""
    references = [item for item in receipt.get("artifacts", ())
                  if not item["key"].startswith("inspection/")]
    return {key: references if key == "artifacts" else value for key, value in receipt.items()
            if key != "inspection" and (key != "artifacts" or receipt["file_ok"] or references)}


def rendering_result(result, output=None):
    """Verify complete published bytes before isolating the readable API contract."""
    code, receipt, markdown = result
    if code == 0 and output is not None:
        ascii_legacy = receipt["route"] in ("pdf", "doc", "presentation") and "inspection" not in receipt
        encoding = "ascii" if ascii_legacy else "utf-8"
        assert output.read_bytes() == markdown.encode(encoding), "published bytes must match the full inspected API output"
    projected = markdown if receipt["route"] == "text" else readable_markdown(markdown)
    return code, rendering_receipt(receipt), projected


def rendering_bytes(payload):
    """Return exact UTF-8 readable prefix bytes without changing any file."""
    return readable_markdown(payload.decode("utf-8")).encode("utf-8")


def rendering_stdout(output):
    """Preserve CLI framing while comparing the readable receipt and Markdown."""
    binary = isinstance(output, bytes)
    text = output.decode("utf-8") if binary else output
    if not text:
        return output
    first, newline, markdown = text.partition("\n")
    if first.endswith("\r"):
        first, newline = first[:-1], "\r" + newline
    receipt = json.loads(first)
    result = json.dumps(rendering_receipt(receipt), ensure_ascii=True, sort_keys=True)
    result += newline + (markdown if receipt["route"] == "text" else readable_markdown(markdown))
    return result.encode("utf-8") if binary else result
